# Standalone MLP Bar Graphs
# -----------------------------
def plot_mlp_scores(prefix):
    df = read_csv_checked(f"{prefix}_MLP_scores.csv")

    labels = [
        f"{row['solver']}\n{row['learning_rate']}\n{row['learning_rate_init']}"
        for _, row in df.iterrows()
    ]

    x = np.arange(len(labels))
    width = 0.4

    plt.figure(figsize=(12, 6))

    plt.bar(x - width/2, df["avg_score"], width, label="Average Score")
    plt.bar(x + width/2, df["max_score"], width, label="Max Score")

    ymin = min(df["avg_score"].min(), df["max_score"].min())
    ymax = max(df["avg_score"].max(), df["max_score"].max())
    padding = (ymax - ymin) * 0.1 if ymax != ymin else 0.01
    plt.ylim(ymin - padding, ymax + padding)

    plt.xticks(x, labels, rotation=45, ha="right")
    plt.xlabel("MLP Hyperparameters")
    plt.ylabel("Score")
    plt.title(f"{prefix} MLP Scores")
    plt.legend()
    plt.tight_layout()
    plt.savefig(f"{prefix}_MLP_scores_bargraph.png")
    plt.close()


